package gy.deckers.studio;
import org.junit.jupiter.api.Test;import publishing.*;import java.awt.*;import java.awt.image.BufferedImage;import java.io.ByteArrayOutputStream;import java.util.Base64;import static org.junit.jupiter.api.Assertions.*;
class PublisherEmptyBoxRepairTest{
 BufferedImage preview(boolean outline,boolean filled){var image=new BufferedImage(200,200,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,200,200);g.setColor(Color.BLACK);if(outline)g.drawRect(20,20,80,40);if(filled)g.fillRect(21,21,78,38);g.dispose();return image;}
 Publication document()throws Exception{var p=new Publication();p.width=100;p.height=100;var e=new Publication.Element();e.type="IMAGE";e.x=10;e.y=10;e.width=40;e.height=20;e.asset="broken";var bytes=new ByteArrayOutputStream();javax.imageio.ImageIO.write(new BufferedImage(20,10,BufferedImage.TYPE_INT_RGB),"png",bytes);p.assets.put("broken",Base64.getEncoder().encodeToString(bytes.toByteArray()));p.pages.get(0).objects.add(e);return p;}
 @Test void sourceConfirmedEmptyBoxBecomesEditableAndSurvivesSave()throws Exception{var p=document();assertEquals(1,PublisherEmptyBoxRepair.restore(p,preview(true,false)));var e=PublicationFiles.read(PublicationFiles.archive(p)).pages.get(0).objects.get(0);assertEquals("RECT",e.type);assertEquals("#ffffff",e.fill);assertTrue(e.asset.isBlank());assertEquals(0,PublisherEmptyBoxRepair.restore(p,preview(true,false)));}
 @Test void genuineDarkArtworkAndUnconfirmedEdgesArePreserved()throws Exception{var p=document();assertEquals(0,PublisherEmptyBoxRepair.restore(p,preview(true,true)));assertEquals(0,PublisherEmptyBoxRepair.restore(p,preview(false,false)));assertEquals("IMAGE",p.pages.get(0).objects.get(0).type);}
 @Test void firstPagePreviewDoesNotInventSecondPageBoxes()throws Exception{var p=document();p.pages.add(new Publication.Page());p.pages.get(1).objects.add(Publication.JSON.fromJson(Publication.JSON.toJson(p.pages.get(0).objects.get(0)),Publication.Element.class));assertEquals(1,PublisherEmptyBoxRepair.restore(p,preview(true,false)));assertEquals("IMAGE",p.pages.get(1).objects.get(0).type);}
}
